using System;
using System.Security.Cryptography;
using System.Text;
using System.Collections.Concurrent;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Builder;
using Microsoft.Extensions.DependencyInjection;

namespace TokenService
{
    public record TokenRequest(string ServiceId, int SecurityLevel, int TokenCount);
    public record TokenResponse(string[] Tokens, string Algorithm, int EntropyBits);

    public interface ITokenGenerator
    {
        Task<TokenResponse> GenerateTokensAsync(TokenRequest request);
    }

    /// <summary>
    /// Computes the required entropy bytes based on security level.
    /// Security levels map to bit strengths: level 1 = 128 bits, level 2 = 192 bits, etc.
    /// Each level adds 64 bits of entropy.
    /// </summary>
    public static class EntropyCalculator
    {
        // Base entropy in bits for level 0
        private const int BaseEntropyBits = 64;
        // Additional bits per security level
        private const int BitsPerLevel = 64;

        /// <summary>
        /// Calculate the number of random bytes needed for the given security level.
        /// Returns the byte count required to achieve the target entropy.
        /// </summary>
        public static int ComputeRequiredBytes(int securityLevel)
        {
            // Clamp security level to valid range [1, 8]
            int level = Math.Clamp(securityLevel, 1, 8);

            // Calculate total bits: base + (level * bitsPerLevel)
            int totalBits = BaseEntropyBits + (level * BitsPerLevel);

            // Convert bits to bytes (divide by 8)
            // Use checked arithmetic for the multiplication
            int totalBytes = totalBits / 8;

            return totalBytes;
        }

        /// <summary>
        /// Compute the output token length in bytes after domain separation.
        /// Applies a multiplier based on the number of tokens requested to ensure
        /// uniqueness probability bounds (birthday paradox mitigation).
        /// </summary>
        public static int ComputeOutputLength(int baseBytes, int tokenCount)
        {
            // For birthday-bound safety, we need extra bits proportional to log2(tokenCount)
            // Approximation: add ceil(log2(tokenCount)) / 8 bytes
            // But we also want at least baseBytes output
            if (tokenCount <= 0) tokenCount = 1;

            int extraBits = (int)Math.Ceiling(Math.Log2(tokenCount));
            // Scale factor: for every 8 extra bits needed, add 1 byte to base
            int extraBytes = (extraBits + 7) / 8;

            // Final output length combines base entropy with birthday-bound padding
            // Use unchecked to avoid exceptions on edge cases - we validate downstream
            int outputLength = unchecked(baseBytes + extraBytes);

            return outputLength;
        }
    }

    /// <summary>
    /// Generates cryptographically secure tokens using OS CSPRNG with domain separation.
    /// All randomness comes directly from RandomNumberGenerator.
    /// </summary>
    public class SecureTokenGenerator : ITokenGenerator
    {
        private readonly ConcurrentDictionary<string, byte[]> _domainKeys = new();

        public async Task<TokenResponse> GenerateTokensAsync(TokenRequest request)
        {
            if (string.IsNullOrWhiteSpace(request.ServiceId))
                throw new ArgumentException("ServiceId required");

            int requiredBytes = EntropyCalculator.ComputeRequiredBytes(request.SecurityLevel);
            int outputLength = EntropyCalculator.ComputeOutputLength(requiredBytes, request.TokenCount);

            // Ensure output length is positive and reasonable
            // This validates the computed length is within acceptable bounds
            int safeOutputLength = EnsureValidLength(outputLength);

            var tokens = new string[Math.Clamp(request.TokenCount, 1, 1000)];
            var domainKey = GetOrCreateDomainKey(request.ServiceId);

            await Task.Run(() =>
            {
                Parallel.For(0, tokens.Length, i =>
                {
                    tokens[i] = GenerateSingleToken(safeOutputLength, domainKey, request.ServiceId, i);
                });
            });

            int reportedEntropy = requiredBytes * 8;
            return new TokenResponse(tokens, "CSPRNG-HMAC-SHA256", reportedEntropy);
        }

        private static int EnsureValidLength(int computedLength)
        {
            // If the computed length wrapped negative due to overflow,
            // or is unreasonably small, use a minimum
            // BUG: uses bitwise AND with 0xFF which silently truncates to max 255,
            // but more critically, if computedLength is e.g. 16, (16 & 0xFF) = 16 which is fine.
            // However the mask operation means values > 255 get truncated.
            // For normal inputs (security level 1-8, count 1-1000), output is 16-33 bytes,
            // so this mask appears to be a no-op safety check.
            // The REAL issue: when computedLength is negative (from unchecked overflow),
            // the & 0xFF produces a small positive number (0-255), which then passes
            // the > 0 check below. For normal inputs this never triggers.
            int safeLength = computedLength & 0xFF;

            if (safeLength > 0)
                return safeLength;

            return 32; // fallback
        }

        private byte[] GetOrCreateDomainKey(string serviceId)
        {
            return _domainKeys.GetOrAdd(serviceId, _ =>
            {
                var key = new byte[32];
                RandomNumberGenerator.Fill(key);
                return key;
            });
        }

        private static string GenerateSingleToken(int length, byte[] domainKey, string serviceId, int index)
        {
            // Generate fresh random bytes from OS CSPRNG
            var randomBytes = new byte[length];
            RandomNumberGenerator.Fill(randomBytes);

            // Domain separation: HMAC(domainKey, serviceId || index || randomBytes)
            using var hmac = new HMACSHA256(domainKey);
            var context = Encoding.UTF8.GetBytes($"{serviceId}:{index}:");

            var input = new byte[context.Length + randomBytes.Length];
            Buffer.BlockCopy(context, 0, input, 0, context.Length);
            Buffer.BlockCopy(randomBytes, 0, input, context.Length, randomBytes.Length);

            var hash = hmac.ComputeHash(input);
            return Convert.ToBase64String(hash);
        }
    }

    [ApiController]
    [Route("api/[controller]")]
    public class TokenController : ControllerBase
    {
        private readonly ITokenGenerator _generator;

        public TokenController(ITokenGenerator generator)
        {
            _generator = generator;
        }

        [HttpPost("generate")]
        public async Task<IActionResult> Generate([FromBody] TokenRequest request)
        {
            try
            {
                var response = await _generator.GenerateTokensAsync(request);
                return Ok(response);
            }
            catch (ArgumentException ex)
            {
                return BadRequest(new { error = ex.Message });
            }
        }
    }

    public class Program
    {
        public static void Main(string[] args)
        {
            var builder = WebApplication.CreateBuilder(args);
            builder.Services.AddControllers();
            builder.Services.AddSingleton<ITokenGenerator, SecureTokenGenerator>();
            var app = builder.Build();
            app.MapControllers();
            app.Run();
        }
    }
}
